using System;using UnityEngine;using UnityCourseLab;
public static class PoolExperimentTests {public static void Run(){var s=new LabSession();s.LoadExperiment("lab10","demo");if(s.Preflight().Count>0)throw new Exception("Pool demo invalid");s.LoadExperiment("lab10","practice");if(s.Preflight().Count==0)throw new Exception("Pool missing reference accepted");var host=new GameObject("Pool test");var prototype=new GameObject("Pool proto");try{var owner=host.AddComponent<LabRuntime>();var field=typeof(LabRuntime).GetField("session",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);var session=(LabSession)field.GetValue(owner);session.LoadExperiment("lab10","demo");session.Start();var pool=host.AddComponent<LabPoolActor>();pool.Owner=owner;pool.Prototype=prototype;pool.Settings=new LabSettings{capacity=1,lifetime=.5f,interval=.5f,speed=1};pool.Begin();var instance=host.transform.GetChild(0).gameObject;for(int i=0;i<8;i++)pool.Step(.5f);if(pool.Created!=1||pool.Reused<=1||pool.Returned<1||pool.Events!=pool.Returned||host.transform.childCount!=1||host.transform.GetChild(0).gameObject!=instance)throw new Exception("Pool reuse/capacity/UnityEvent failed");}finally{UnityEngine.Object.DestroyImmediate(host);UnityEngine.Object.DestroyImmediate(prototype);}Debug.Log("COURSE_LAB_POOL_TESTS_PASSED");}}
